using System.Reflection;
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100PaysAnApprovedTotalOf95()
    {
        var pricingTypes = new[] { typeof(ApplicationMarker).Assembly, typeof(DomainMarker).Assembly }
            .SelectMany(a => a.GetExportedTypes())
            .Where(t => t != typeof(ApplicationMarker) && t != typeof(DomainMarker))
            .ToList();

        Assert.True(pricingTypes.Count > 0,
            "No checkout pricing capability exists, so a Gold customer with subtotal 100.00 cannot be priced at 95.00.");
    }
}
